'use strict';
const C=CampusCore;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateToday=()=>new Date().toLocaleDateString('en-CA');
let user=null,state=null,error='',notice='',editing=null;
try{const saved=JSON.parse(localStorage.getItem('campus.active')||'null');if(saved){user=C.identity(saved.name,saved.school);state=C.load(localStorage,user);}}catch(e){error=e.message;}
const urlRoute=()=>location.hash.slice(1)||'home';
function write(next){try{const saved=C.save(localStorage,next);state=saved;notice='Saved';error='';render(false);}catch(e){error='Your changes could not be saved. Check browser storage and try again.';render(false);}}
function update(fn){try{write(fn());}catch(e){error=e.message;render(false);}}
function status(){return `${error?`<div class="feedback error" role="alert">${esc(error)}<button data-dismiss aria-label="Dismiss message">×</button></div>`:''}${notice?`<div class="feedback" role="status">${esc(notice)}<button data-dismiss aria-label="Dismiss message">×</button></div>`:''}`;}
function schoolOptions(value=''){return `<option value="" ${!value?'selected':''} disabled>Choose a school</option>${C.schools.map(s=>`<option value="${s}" ${value===s?'selected':''}>${s}</option>`).join('')}`;}
function enter(){document.title='Welcome to Campus';document.querySelector('header').innerHTML='<a class="brand" href="#home"><span class="mark">c.</span>campus</a>';document.querySelector('footer').innerHTML='<span>Made for a simpler campus day.</span>';document.querySelector('main').innerHTML=`<div class="entry"><div class="entry-copy"><div class="eyebrow">YOUR DAY, IN ONE PLACE</div><h1>Campus life,<br><em>made clearer.</em></h1><p>Keep your courses, classes, tasks and progress together.</p><div class="entry-points"><span>Plan your week</span><span>Know what’s next</span><span>Stay on track</span></div></div><form id="enter-form" class="entry-card"><div class="eyebrow">GET STARTED</div><h2>Make this space yours.</h2><p>Enter your name and school to open your campus workspace.</p>${status()}<label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" required minlength="2" maxlength="80" value="${esc(user?.name||'')}"><label for="school">School</label><select id="school" name="school" required>${schoolOptions(user?.school)}</select><button class="primary full" type="submit">Continue to Campus →</button><p class="fine">Your information stays in this browser. Anyone using this browser and name can open this workspace.</p></form></div>`;document.querySelector('#enter-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);try{const next=C.identity(data.get('name'),data.get('school'));const loaded=C.load(localStorage,next);localStorage.setItem('campus.active',JSON.stringify(next));user=next;state=loaded;error='';notice='';location.hash='home';render();}catch(err){error=err.message;notice='';enter();}};}
function shell(route){const nav=[['home','Home'],['courses','Courses'],['timetable','Timetable'],['tasks','Tasks'],['results','Progress']];document.querySelector('header').innerHTML=`<a class="brand" href="#home"><span class="mark">c.</span>campus</a><nav aria-label="Main navigation">${nav.map(([id,label])=>`<a href="#${id}" ${route===id?'class="active" aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="account" href="#account" ${route==='account'?'aria-current="page"':''}>${esc(user.name.split(' ')[0])}<span class="account-dot">${esc(user.name[0].toUpperCase())}</span></a>`;document.querySelector('footer').innerHTML=`<a class="brand" href="#home">campus.</a><span>${esc(user.school)}</span><div class="footer-links"><a href="#about">About</a><a href="#account">Account</a></div>`;}
const heading=(over,title,sub)=>`<div class="portal-heading"><div><div class="eyebrow">${over}</div><h1>${title}</h1><p>${sub}</p></div><span class="school-pill">${esc(user.school)}</span></div>`;
const courseName=id=>state.courses.find(c=>c.id===id)?.code||'';
const empty=(title,body,href,label)=>`<div class="empty-state"><div class="empty-icon" aria-hidden="true">＋</div><h3>${title}</h3><p>${body}</p>${href?`<a class="primary" href="#${href}">${label} →</a>`:''}</div>`;
function nextClass(){const now=new Date(),today=(now.getDay()+6)%7,min=now.getHours()*60+now.getMinutes();return state.courses.map(c=>({course:c,delta:((c.day-today+7)%7)*1440+Number(c.start.slice(0,2))*60+Number(c.start.slice(3))-min})).map(x=>({...x,delta:x.delta<0?x.delta+10080:x.delta})).sort((a,b)=>a.delta-b.delta)[0]?.course;}
function home(){const upcoming=state.tasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4),next=nextClass();return `${heading('YOUR SPACE',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${esc(user.name.split(' ')[0])}.`,'Everything you need for a smoother campus day.')}<div class="home-feature"><div><span class="eyebrow">UP NEXT</span>${next?`<h2>${esc(next.code)}</h2><p>${esc(next.title)}</p><div class="feature-meta">${C.days[next.day]} · ${next.start}–${next.end}${next.room?` · ${esc(next.room)}`:''}</div>`:`<h2>Your week starts here.</h2><p>Add a course and its class time to see what’s next.</p>`}<a href="#${next?'timetable':'courses'}">${next?'See timetable':'Add a course'} →</a></div><div class="feature-symbol" aria-hidden="true">↗</div></div><div class="home-grid"><section class="panel"><div class="panel-title"><div><div class="eyebrow">STAY ORGANISED</div><h2>Coming up</h2></div><a href="#tasks">All tasks →</a></div>${upcoming.length?upcoming.map(t=>`<div class="list-row"><div><strong>${esc(t.title)}</strong><span>${t.courseId?esc(courseName(t.courseId))+' · ':''}${esc(t.due)}</span></div><button class="quiet" data-done="${t.id}" aria-label="Complete ${esc(t.title)}">Done</button></div>`).join(''):empty('Nothing due yet','Add a task to keep the important dates in view.','tasks','Add a task')}</section><section class="panel"><div class="panel-title"><div><div class="eyebrow">YOUR SEMESTER</div><h2>At a glance</h2></div></div><div class="glance"><strong>${state.courses.length}</strong><span>courses in your planner</span></div><div class="glance"><strong>${state.tasks.filter(t=>!t.done).length}</strong><span>open tasks</span></div><div class="quick-links"><a href="#courses">Manage courses ↗</a><a href="#results">View progress ↗</a></div></section></div>`;}
function courseForm(record){return `<form id="course-form" class="form-grid"><input type="hidden" name="id" value="${esc(record?.id||'')}"><label>Course code<input name="code" required maxlength="15" value="${esc(record?.code||'')}"></label><label>Course title<input name="title" required maxlength="100" value="${esc(record?.title||'')}"></label><label>Units<input name="units" type="number" min="1" max="6" required value="${record?.units||''}"></label><label>Class day<select name="day" required><option value="" disabled ${record?'':'selected'}>Choose a day</option>${C.days.map((d,i)=>`<option value="${i}" ${record?.day===i?'selected':''}>${d}</option>`).join('')}</select></label><label>Starts<input name="start" type="time" required value="${record?.start||''}"></label><label>Ends<input name="end" type="time" required value="${record?.end||''}"></label><label class="wide">Location (optional)<input name="room" maxlength="80" value="${esc(record?.room||'')}"></label><div class="wide form-actions"><button class="primary" type="submit">${record?'Save course':'Add course'}</button><button class="quiet" type="button" data-cancel>Cancel</button></div></form>`;}
function courses(){return `${heading('COURSE PLANNER','Your courses.','Add the classes you attend. Your timetable will update automatically.')}<div class="page-actions"><span>${state.courses.length} course${state.courses.length===1?'':'s'} · ${state.courses.reduce((n,c)=>n+c.units,0)} units</span><button class="primary" data-add-course>+ Add course</button></div><div id="editor"></div>${state.courses.length?`<div class="course-cards">${state.courses.sort((a,b)=>a.code.localeCompare(b.code)).map(c=>`<article class="course-card"><div><span class="course-tag">${esc(c.code)}</span><h2>${esc(c.title)}</h2><p>${c.units} unit${c.units===1?'':'s'} · ${C.days[c.day]} ${c.start}–${c.end}${c.room?` · ${esc(c.room)}`:''}</p></div><div class="row-actions"><button class="quiet" data-edit-course="${c.id}">Edit</button><button class="quiet danger" data-delete-course="${c.id}">Remove</button></div></article>`).join('')}</div>`:empty('No courses yet','Add your first course to start building your week.',null,null)}`;}
function timetable(){return `${heading('YOUR WEEK','Timetable.','A simple view of where you need to be.')}<div class="week-grid">${C.days.map((d,i)=>`<section class="day-column"><h2>${d}</h2>${state.courses.filter(c=>c.day===i).sort((a,b)=>a.start.localeCompare(b.start)).map(c=>`<article class="class-card"><span>${c.start}–${c.end}</span><h3>${esc(c.code)}</h3><p>${esc(c.title)}</p>${c.room?`<small>${esc(c.room)}</small>`:''}</article>`).join('')||'<p class="free-day">No classes</p>'}</section>`).join('')}</div>${!state.courses.length?empty('A clear week ahead','Add courses to fill your timetable.','courses','Add a course'):''}<div class="page-actions"><span>Changes save automatically.</span><button class="quiet" id="export-calendar" ${state.courses.length?'':'disabled'}>Export calendar</button></div>`;}
function taskForm(record){return `<form id="task-form" class="form-grid"><input type="hidden" name="id" value="${esc(record?.id||'')}"><label class="wide">What needs doing?<input name="title" required maxlength="120" value="${esc(record?.title||'')}"></label><label>Due date<input name="due" type="date" required value="${esc(record?.due||'')}"></label><label>Course (optional)<select name="courseId"><option value="">No course</option>${state.courses.map(c=>`<option value="${c.id}" ${record?.courseId===c.id?'selected':''}>${esc(c.code)}</option>`).join('')}</select></label><div class="wide form-actions"><button class="primary" type="submit">${record?'Save task':'Add task'}</button><button class="quiet" type="button" data-cancel>Cancel</button></div></form>`;}
function tasks(){const open=state.tasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due)),done=state.tasks.filter(t=>t.done);return `${heading('YOUR TO-DOS','Keep moving.','Keep assignments, readings and deadlines in one place.')}<div class="page-actions"><span>${open.length} open · ${done.length} completed</span><button class="primary" data-add-task>+ Add task</button></div><div id="editor"></div>${state.tasks.length?`<section class="panel"><h2>To do</h2>${open.length?open.map(taskRow).join(''):'<p class="muted">You’re all caught up.</p>'}</section><section class="panel"><h2>Completed</h2>${done.length?done.map(taskRow).join(''):'<p class="muted">Completed tasks will appear here.</p>'}</section>`:empty('One less thing to remember','Add a task and keep your next deadline close.','',null)}`;}
function taskRow(t){return `<article class="task-row"><label><input type="checkbox" data-toggle-task="${t.id}" ${t.done?'checked':''}><span><strong>${esc(t.title)}</strong><small>${t.courseId?esc(courseName(t.courseId))+' · ':''}Due ${esc(t.due)}</small></span></label><div class="row-actions"><button class="quiet" data-edit-task="${t.id}">Edit</button><button class="quiet danger" data-delete-task="${t.id}">Remove</button></div></article>`;}
function resultForm(record){return `<form id="result-form" class="form-grid"><input type="hidden" name="id" value="${esc(record?.id||'')}"><label>Course<select name="courseId" required><option value="" disabled ${record?'':'selected'}>Choose a course</option>${state.courses.map(c=>`<option value="${c.id}" ${record?.courseId===c.id?'selected':''}>${esc(c.code)} · ${esc(c.title)}</option>`).join('')}</select></label><label>Score out of 100<input name="score" type="number" min="0" max="100" step="0.01" required value="${record?.score??''}"></label><div class="wide form-actions"><button class="primary" type="submit">${record?'Save result':'Add result'}</button><button class="quiet" type="button" data-cancel>Cancel</button></div></form>`;}
function results(){const gpa=C.gpa(state);return `${heading('PERSONAL PROGRESS','See how you’re doing.','Record your own results to track progress. Only you can verify official university results.')}<div class="page-actions"><span>${state.results.length} recorded result${state.results.length===1?'':'s'}</span><button class="primary" data-add-result ${state.courses.length?'':'disabled'}>+ Add result</button></div><div id="editor"></div>${state.results.length?`<div class="progress-summary"><div><span>Weighted GPA · 5 point scale</span><strong>${gpa.toFixed(2)}</strong></div><p>Calculated from the units and scores you entered.</p></div><section class="panel table-wrap"><table><thead><tr><th>Course</th><th>Units</th><th>Score</th><th>Grade</th><th></th></tr></thead><tbody>${state.results.map(r=>{const c=state.courses.find(x=>x.id===r.courseId);return `<tr><td>${esc(c?.code||'Removed course')}</td><td>${c?.units||'—'}</td><td>${r.score}</td><td>${C.grade(r.score)[0]}</td><td><button class="quiet" data-edit-result="${r.id}">Edit</button> <button class="quiet danger" data-delete-result="${r.id}">Remove</button></td></tr>`}).join('')}</tbody></table></section>`:empty('Your progress, in your hands',state.courses.length?'Add a result when you have a score to record.':'Add a course first, then record your results.',state.courses.length?null:'courses',state.courses.length?null:'Add a course')}`;}
function account(){return `${heading('YOUR ACCOUNT','A space that feels like yours.','Your name and school shape this workspace.')}<div class="account-grid"><section class="panel"><h2>${esc(user.name)}</h2><p>${esc(user.school)}</p><p class="fine">Sign-in is intentionally simple. This workspace is stored on this browser under your name and school. Anyone entering the same details here can open it.</p><button class="quiet" id="sign-out">Sign out</button></section><section class="panel"><h2>Your information</h2><p>Export a copy of your courses, tasks and results whenever you need one.</p><button class="quiet" id="export-data">Export my data</button></section></div>`;}
function about(){const people=['Atuba Chidubem Sean','Awofiranye Favor Opeyemi','Bantefa Gbolahan Nifemi','Divine Dominion Saviour','Edun Meyiwa-Meyigbene Nifemi','Egerega Joel Ndubuisi','Ejike Chiamaka Joan'];return `${heading('ABOUT CAMPUS','A more straightforward campus day.','Campus brings the pieces of student life into one clear space.')}<section class="panel about-story"><h2>Built around your day.</h2><p>See your next class. Keep deadlines nearby. Make sense of your week and your progress. Campus is made to help students move through the semester with less friction.</p><p>Your courses and scores are entered by you. They are not official university records.</p></section><section class="panel"><div class="eyebrow">THE PEOPLE BEHIND CAMPUS</div><div class="people-list">${people.map(p=>`<div>${esc(p)}</div>`).join('')}</div></section>`;}
function render(scroll=true){if(!user||!state){enter();return;}let route=urlRoute();const pages={home,courses,timetable,tasks,results,account,about};if(!pages[route])route='home';shell(route);document.title=`${route[0].toUpperCase()+route.slice(1)} · Campus`;document.querySelector('main').innerHTML=`<div class="wrap portal">${status()}${pages[route]()}</div><dialog id="confirm-dialog"><h2 id="dialog-title"></h2><p id="dialog-body"></p><div class="form-actions"><button class="quiet" id="cancel-dialog">Cancel</button><button class="primary" id="confirm-dialog-action">Remove</button></div></dialog>`;bind();if(scroll)window.scrollTo(0,0);}
function confirmDelete(title,body,fn){const d=document.querySelector('#confirm-dialog');document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;document.querySelector('#cancel-dialog').onclick=()=>d.close();document.querySelector('#confirm-dialog-action').onclick=()=>{d.close();fn();};d.showModal();}
function editor(form){document.querySelector('#editor').innerHTML=`<section class="panel edit-panel"><h2>${editing?'Edit':'Add'} ${form}</h2>${form==='course'?courseForm(editing):form==='task'?taskForm(editing):resultForm(editing)}</section>`;const node=document.querySelector(`#${form}-form`);node.onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(node));try{const next=C[form](state,input);state=C.save(localStorage,next);error='';notice='Saved';editing=null;render(false);}catch(err){let alert=node.querySelector('[role=alert]');if(!alert){alert=document.createElement('p');alert.setAttribute('role','alert');alert.className='form-error';node.prepend(alert);}alert.textContent=err.message;}};document.querySelector('[data-cancel]').onclick=()=>{editing=null;document.querySelector('#editor').innerHTML='';};node.querySelector('input:not([type=hidden])')?.focus();}
function bind(){document.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=()=>{error='';notice='';render(false);});const add=(type)=>{const button=document.querySelector(`[data-add-${type}]`);if(button)button.onclick=()=>{editing=null;editor(type);};document.querySelectorAll(`[data-edit-${type}]`).forEach(b=>b.onclick=()=>{editing=state[type==='course'?'courses':type==='task'?'tasks':'results'].find(x=>x.id===b.dataset[`edit${type[0].toUpperCase()+type.slice(1)}`]);editor(type);});};
  for(const type of ['course','task','result'])add(type);
  document.querySelectorAll('[data-delete-course]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteCourse,c=state.courses.find(x=>x.id===id);confirmDelete(`Remove ${c.code}?`,'This also removes its tasks and recorded result.',()=>write({...state,courses:state.courses.filter(x=>x.id!==id),tasks:state.tasks.filter(x=>x.courseId!==id),results:state.results.filter(x=>x.courseId!==id)}));});
  document.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=()=>confirmDelete('Remove task?','This task will be removed from your list.',()=>write({...state,tasks:state.tasks.filter(t=>t.id!==b.dataset.deleteTask)})));
  document.querySelectorAll('[data-delete-result]').forEach(b=>b.onclick=()=>confirmDelete('Remove result?','This score will be removed from your progress.',()=>write({...state,results:state.results.filter(r=>r.id!==b.dataset.deleteResult)})));
  document.querySelectorAll('[data-toggle-task]').forEach(b=>b.onchange=()=>write({...state,tasks:state.tasks.map(t=>t.id===b.dataset.toggleTask?{...t,done:!t.done}:t)}));document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>write({...state,tasks:state.tasks.map(t=>t.id===b.dataset.done?{...t,done:true}:t)}));
  const out=document.querySelector('#export-data');if(out)out.onclick=()=>download('campus-data.json',JSON.stringify(state,null,2),'application/json');
  const calendar=document.querySelector('#export-calendar');if(calendar)calendar.onclick=exportCalendar;
  const signout=document.querySelector('#sign-out');if(signout)signout.onclick=()=>{localStorage.removeItem('campus.active');user=null;state=null;location.hash='home';enter();};
}
function download(name,value,type){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCalendar(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Campus//Student Planner//EN'];for(const c of state.courses){const next=new Date(),delta=(c.day-(next.getDay()+6)%7+7)%7;next.setDate(next.getDate()+delta);const date=`${next.getFullYear()}${String(next.getMonth()+1).padStart(2,'0')}${String(next.getDate()).padStart(2,'0')}`;lines.push('BEGIN:VEVENT',`UID:${c.id}@campus.local`,`DTSTART:${date}T${c.start.replace(':','')}00`,`DTEND:${date}T${c.end.replace(':','')}00`,'RRULE:FREQ=WEEKLY;COUNT=12',`SUMMARY:${c.code} - ${c.title.replace(/[\n,;]/g,' ')}`,`LOCATION:${c.room.replace(/[\n,;]/g,' ')}`,'END:VEVENT');}lines.push('END:VCALENDAR');download('campus-timetable.ics',lines.join('\r\n'),'text/calendar');}
window.addEventListener('hashchange',()=>{error='';notice='';editing=null;render();});window.addEventListener('storage',e=>{if(!user)return;if(e.key===C.key(user.name,user.school)){try{state=C.load(localStorage,user);notice='Updated from another tab';render(false);}catch{error='Could not load changes from another tab';render(false);}}});render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


